24	// freshVersionSpec is a legal registration that shares no ID with the
25	// corrupt-archive fixture.
26	const freshVersionSpec = `{"id":"fresh","rules":{"sandwich":{"enabled":true,"severity":2},"displacement":{"enabled":true,"severity":3,"multiplier":3}}}`
