81				// The new version is stored exactly as submitted and is usable;
82				// the corrupt sibling was not repaired by the registration and
83				// is still refused on its own merits. (GetVersion/ListVersions
84				// decode every stored version, so the wrong-typed sibling cases
85				// are read back through the raw document instead.)
86				stored, err := ParseRuleVersion(after.Versions[len(after.Versions)-1])
