91					t.Fatalf("newly registered version not enableable: %v", err)
92				}
93				if _, err := EnableVersion(dir, "candC"); !errors.Is(err, ErrCorruptVersion) {
94					t.Fatalf("corrupt sibling silently repaired by registration: %v", err)
95				}
96				if _, err := ReplayWithVersion(strings.NewReader(sandwichInput), dir, "candC"); !errors.Is(err, ErrCorruptVersion) {
