mkdir -p cmd/probe && cat > cmd/probe/main.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
)

func main() {
	raw, _ := os.ReadFile(os.Args[1])
	fmt.Printf("len=%d\n", len(raw))
	dec := json.NewDecoder(bytes.NewReader(raw))
	for {
		tok, err := dec.Token()
		fmt.Printf("tok=%#v off=%d err=%v\n", tok, dec.InputOffset(), err)
		if err != nil {
			break
		}
	}
}
EOF
D=$(mktemp -d)
printf '%s' '{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}' > $D/spec.json
go run ./cmd/probe $D/spec.json
rm -rf cmd/probe

